import { loadFont as loadJakarta } from "@remotion/google-fonts/PlusJakartaSans";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadBebas } from "@remotion/google-fonts/BebasNeue";
import React from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from "remotion";

// WESLEY · serviço de TV por R$ 30 (futebol, canais em 4K/Full HD, filmes e séries, instala em Smart TV e TV Android).
// Pedido: "design dark e clean"; referência: venda de iPhones (cards escuros, brilho leve só no destaque).
// Só veio áudio (sem logo nem fotos): jeito motion. Fundo preto liso, cards grafite, um acento ciano; verde só no "ok",
// vermelho só no "caro". Logos das plataformas desenhados em texto (sem acesso para baixar os oficiais).
// Texto entra e fica parado; o movimento contínuo fica nos objetos (TV, bola, cards, pôsteres).
// Tempos = tempos da voz final ((arquivo do cliente) 31,2 s, o locutor); o vídeo tem LEAD de entrada.

const { fontFamily: H } = loadJakarta("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: F } = loadInter("normal", { weights: ["400", "500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: B } = loadBebas("normal", { weights: ["400"], subsets: ["latin"] });

export const WES_FPS = 30;
const LEAD = 0.2;
export const WES_FRAMES = Math.round((LEAD + 31.8) * WES_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const BG = "#07080A";
const CARD = "#121418";
const CARD2 = "#1A1D22";
const LINE = "rgba(255,255,255,0.08)";
const FG = "#F4F5F7";
const MUTED = "#8C919A";
const ACC = "#2FD3F2";
const OK = "#34D27B";
const RED = "#FF4150";
const HERO = `radial-gradient(90% 45% at 50% 38%, rgba(47,211,242,0.07), rgba(47,211,242,0) 70%), ${BG}`;

// trocas de cena
const T2 = 1.5, T3 = 5.3, T4 = 8.45, T5 = 13.2, T6 = 15.15, T7 = 18.35, T8 = 24.95, T9 = 28.4;

const blurIn = (t: number, at: number, d = 0.4): React.CSSProperties => {
  const e = k(t, at, d);
  return { opacity: Math.min(1, e * 1.6), filter: `blur(${((1 - e) * 16).toFixed(1)}px)`, transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})` };
};

type L = [string, number, ("acc" | "red" | "pill")?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; weight?: number }> = ({ t, items, size, top, color = FG, weight = 800 }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.12 }}>
    {items.map(([w, at, hl], i) => (
      <div key={i} style={{ fontFamily: H, fontWeight: weight, fontSize: size, lineHeight: 1.1, letterSpacing: "-0.035em", whiteSpace: "nowrap", color: hl === "acc" ? ACC : hl === "red" ? RED : hl === "pill" ? BG : color, ...(hl === "pill" ? { background: ACC, padding: `${size * 0.04}px ${size * 0.34}px ${size * 0.1}px`, borderRadius: size, boxShadow: "0 0 60px rgba(47,211,242,0.35)" } : {}), ...blurIn(t, at) }}>
        {w}
      </div>
    ))}
  </div>
);

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string }>;
const sv = (s: number, c: string, ch: React.ReactNode, w = 2) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoHand: Ico = ({ s, c }) => sv(s, c, <><path d="M18 11V6a2 2 0 0 0-4 0" /><path d="M14 10V4a2 2 0 0 0-4 0v2" /><path d="M10 10.5V6a2 2 0 0 0-4 0v8" /><path d="M18 8a2 2 0 1 1 4 0v6a8 8 0 0 1-8 8h-2c-2.8 0-4.5-.86-6-2.34l-3.6-3.6a2 2 0 0 1 2.83-2.82L7 15" /></>, 1.8);
const IcoCheck: Ico = ({ s, c }) => sv(s, c, <path d="M5 12.5l4.5 4.5L19 7.5" />, 2.8);
const IcoLock: Ico = ({ s, c }) => sv(s, c, <><rect x="4.5" y="10.5" width="15" height="10" rx="2.5" /><path d="M8 10.5V7.5a4 4 0 0 1 8 0v3" /></>);
const IcoTv: Ico = ({ s, c }) => sv(s, c, <><rect x="2.5" y="4.5" width="19" height="13" rx="2.5" /><path d="M8 21h8M12 17.5V21" /></>);
const IcoArrow: Ico = ({ s, c }) => sv(s, c, <path d="M5 12h14M13 6l6 6-6 6" />, 2.6);
const IcoAndroid: Ico = ({ s, c }) => sv(s, c, <><path d="M5 16V11a7 7 0 0 1 14 0v5z" /><path d="M7.5 6.5L6 4.5M16.5 6.5L18 4.5" /><circle cx="9.3" cy="11" r="0.6" fill={c} /><circle cx="14.7" cy="11" r="0.6" fill={c} /></>);
const Ball: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="-50 -50 100 100">
    <circle r="47" fill="#F7F7F7" stroke="#0B0C0E" strokeWidth="3" />
    <polygon points="0,-17 16,-5 10,14 -10,14 -16,-5" fill="#0B0C0E" />
    {[0, 72, 144, 216, 288].map((a) => (
      <g key={a} transform={`rotate(${a})`}>
        <line x1="0" y1="-17" x2="0" y2="-34" stroke="#0B0C0E" strokeWidth="3" />
        <polygon points="0,-46 -10,-36 -7,-31 7,-31 10,-36" fill="#0B0C0E" />
      </g>
    ))}
  </svg>
);

const Card: React.FC<{ w: number; h: number; children: React.ReactNode; style?: React.CSSProperties; glow?: string }> = ({ w, h, children, style, glow }) => (
  <div style={{ width: w, height: h, borderRadius: 34, background: `linear-gradient(180deg, ${CARD2}, ${CARD})`, border: `2px solid ${glow ?? LINE}`, boxSizing: "border-box", position: "relative", overflow: "hidden", boxShadow: `0 30px 60px rgba(0,0,0,0.5)${glow ? `, 0 0 50px ${glow}55` : ""}`, ...style }}>
    {children}
  </div>
);

// ───────── campo de futebol desenhado (tela da TV) ─────────
const Field: React.FC<{ w: number; h: number; t: number }> = ({ w, h, t }) => (
  <div style={{ position: "absolute", inset: 0, background: "repeating-linear-gradient(90deg, #0F4A2A 0 80px, #11542F 80px 160px)" }}>
    <svg width={w} height={h} style={{ position: "absolute", inset: 0 }}>
      <g stroke="rgba(255,255,255,0.55)" strokeWidth="4" fill="none">
        <rect x="24" y="24" width={w - 48} height={h - 48} />
        <line x1={w / 2} y1="24" x2={w / 2} y2={h - 24} />
        <circle cx={w / 2} cy={h / 2} r={h * 0.2} />
        <rect x="24" y={h * 0.28} width={w * 0.12} height={h * 0.44} />
        <rect x={w - 24 - w * 0.12} y={h * 0.28} width={w * 0.12} height={h * 0.44} />
      </g>
    </svg>
    <div style={{ position: "absolute", left: w * 0.5 - 40 + Math.sin(t * 1.7) * w * 0.28, top: h * 0.5 - 40 + Math.sin(t * 2.9) * h * 0.22, transform: `rotate(${(t * 260).toFixed(0)}deg)` }}><Ball s={80} /></div>
  </div>
);

// ───────── logos das plataformas (em texto) ─────────
const Brand: React.FC<{ n: number; w: number; h: number }> = ({ n, w, h }) => {
  const box: React.CSSProperties = { width: w, height: h, borderRadius: 24, display: "flex", alignItems: "center", justifyContent: "center", position: "relative", overflow: "hidden" };
  if (n === 0) return <div style={{ ...box, background: "#000" }}><span style={{ fontFamily: B, fontSize: h * 0.78, color: "#E50914", letterSpacing: "0.02em", transform: "scaleY(1.08)" }}>NETFLIX</span></div>;
  if (n === 1)
    return (
      <div style={{ ...box, background: "#0F1B26", flexDirection: "column" }}>
        <span style={{ fontFamily: F, fontWeight: 800, fontSize: h * 0.36, color: FG, letterSpacing: "-0.03em", lineHeight: 1 }}>prime video</span>
        <svg width={h * 1.4} height={h * 0.2} viewBox="0 0 140 20" style={{ marginTop: 4, marginLeft: -h * 0.9 }}><path d="M4 4 Q 60 22 118 6" stroke="#1A98FF" strokeWidth="6" fill="none" strokeLinecap="round" /><path d="M110 2 L124 6 L114 14" stroke="#1A98FF" strokeWidth="5" fill="none" strokeLinecap="round" strokeLinejoin="round" /></svg>
      </div>
    );
  if (n === 2)
    return (
      <div style={{ ...box, background: "linear-gradient(135deg, #0B1240, #12379A)" }}>
        <svg width={w * 0.9} height={h} viewBox="0 0 300 120" style={{ position: "absolute", inset: 0, margin: "auto" }}><path d="M40 80 Q 150 -10 262 62" stroke="url(#dg)" strokeWidth="4" fill="none" strokeLinecap="round" /><defs><linearGradient id="dg"><stop offset="0" stopColor="#1A3C9E" stopOpacity="0" /><stop offset="0.7" stopColor="#7FD8FF" /><stop offset="1" stopColor="#FFFFFF" /></linearGradient></defs></svg>
        <span style={{ fontFamily: H, fontWeight: 700, fontStyle: "italic", fontSize: h * 0.42, color: "#fff", letterSpacing: "-0.03em", marginTop: h * 0.08 }}>Disney+</span>
      </div>
    );
  return (
    <div style={{ ...box, background: "linear-gradient(135deg, #3A1A9E, #0B2BD6)" }}>
      <span style={{ fontFamily: H, fontWeight: 800, fontSize: h * 0.42, color: "#fff", letterSpacing: "-0.02em" }}>HBO <span style={{ fontWeight: 700 }}>Max</span></span>
    </div>
  );
};

// ───────── cena 1 · calma, não pula! ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  const e = pop(t, -0.15, 0.55);
  const shake = Math.sin(t * 38) * 9 * Math.max(0, 1 - t / 0.7);
  return (
    <AbsoluteFill style={{ background: HERO }}>
      <div style={{ position: "absolute", left: 540 - 170, top: 400, width: 340, height: 340, borderRadius: 340, background: CARD, border: `3px solid ${ACC}`, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 0 90px rgba(47,211,242,0.35)", transform: `scale(${(e * (1 + 0.06 * bump(t, 0.46, 0.35))).toFixed(4)}) rotate(${(shake + (1 - e) * -40).toFixed(1)}deg)` }}>
        <IcoHand s={190} c={FG} />
