        <Card w={W} h={Hh} glow={off > 0.5 ? RED : undefined}>
          <div style={{ position: "absolute", inset: 14, borderRadius: 22, overflow: "hidden", transform: `translateX(${glitch.toFixed(1)}px)` }}>
            <Field w={W - 28} h={Hh - 28} t={t} />
            <div style={{ position: "absolute", left: 22, top: 22, display: "flex", gap: 10, alignItems: "center", background: "rgba(0,0,0,0.65)", borderRadius: 40, padding: "10px 22px", fontFamily: F, fontWeight: 800, fontSize: 30, color: FG }}>
              <div style={{ width: 16, height: 16, borderRadius: 16, background: RED, opacity: 0.5 + 0.5 * Math.sin(t * 8) }} />AO VIVO
            </div>
            <div style={{ position: "absolute", inset: 0, background: `rgba(7,8,10,${(0.9 * off).toFixed(2)})`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18 }}>
              <div style={{ opacity: off, transform: `scale(${(0.6 + 0.4 * pop(t, 3.2, 0.45)).toFixed(3)})` }}><IcoLock s={120} c={RED} /></div>
              <div style={{ opacity: off, fontFamily: F, fontWeight: 700, fontSize: 40, color: FG }}>Conteúdo indisponível</div>
