        </Card>
      </div>
      <Lines t={t} top={1150} size={78} items={[["e não consegue", 3.18], ["assistir os jogos?", 3.96, "red"]]} />
    </AbsoluteFill>
  );
};

// ───────── cena 3 · por R$ 30, isso acaba ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const p = pop(t, 5.92, 0.55);
  const ring = lin(t, 5.95, 6.9);
  const ok = pop(t, 7.79, 0.45);
  return (
    <AbsoluteFill style={{ background: HERO }}>
      <Lines t={t} top={470} size={76} color={MUTED} weight={700} items={[["por apenas", 5.6]]} />
