        <div style={{ position: "absolute", width: 500 + ring * 700, height: 500 + ring * 700, borderRadius: 3000, border: `${(8 * (1 - ring)).toFixed(1)}px solid ${ACC}`, transform: "translate(-50%, -50%)", opacity: 0.5 * (1 - ring) }} />
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 590, display: "flex", justifyContent: "center", alignItems: "flex-start", opacity: Math.min(1, p * 2), transform: `scale(${(p * (1 + 0.04 * bump(t, 5.92, 0.4))).toFixed(4)})` }}>
        <span style={{ fontFamily: H, fontWeight: 800, fontSize: 120, color: ACC, marginTop: 52, marginRight: 14 }}>R$</span>
        <span style={{ fontFamily: H, fontWeight: 800, fontSize: 380, lineHeight: 1, letterSpacing: "-0.05em", color: FG, textShadow: "0 0 70px rgba(47,211,242,0.35)" }}>30</span>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1110, display: "flex", justifyContent: "center", alignItems: "center", gap: 26 }}>
        <div style={{ width: 104, height: 104, borderRadius: 104, background: OK, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${ok.toFixed(3)}) rotate(${((1 - ok) * -90).toFixed(1)}deg)`, boxShadow: "0 0 50px rgba(52,210,123,0.4)" }}><IcoCheck s={64} c={BG} /></div>
        <div style={{ fontFamily: H, fontWeight: 800, fontSize: 92, letterSpacing: "-0.035em", color: FG, ...blurIn(t, 7.79) }}>isso acaba.</div>
