// ───────── cena 4 · futebol, canais abertos, 4K e Full HD ─────────
const Row: React.FC<{ t: number; at: number; icon: React.ReactNode; title: string; sub: string; y: number }> = ({ t, at, icon, title, sub, y }) => {
