  [T8, S8, (p) => `circle(${(p * 125).toFixed(1)}% at 50% 90%)`],
  [T9, S9, (p) => `inset(0 0 0 ${((1 - p) * 100).toFixed(2)}%)`],
];

export const WesleyTv: React.FC = () => {
  const t = useCurrentFrame() / WES_FPS - LEAD;
  return (
    <AbsoluteFill style={{ background: BG }}>
      {SCENES.map(([at, S, clip], i) => {
        const end = i + 1 < SCENES.length ? SCENES[i + 1][0] + 0.45 : 1e9;
        if (t < at || t >= end) return null;
        const p = i === 0 ? 1 : interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: INOUT });
        return (
          <AbsoluteFill key={i} style={p < 1 ? { clipPath: clip(p) } : undefined}>
            <AbsoluteFill style={{ transform: `translateY(${DOWN[i]}px)` }}><S t={t} /></AbsoluteFill>
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

